"""Operating system-related utility functions for Sphinx."""

from __future__ import annotations

import contextlib
import filecmp
import os
import re
import shutil
import sys
import unicodedata
from io import StringIO
from os import path
from typing import TYPE_CHECKING, Any

from sphinx.deprecation import _deprecation_warning

if TYPE_CHECKING:
    from collections.abc import Iterator

# SEP separates path elements in the canonical file names
#
# Define SEP as a manifest constant, not so much because we expect it to change
# in the future as to avoid the suspicion that a stray "/" in the code is a
# hangover from more *nix-oriented origins.
SEP = "/"


def os_path(canonical_path: str, /) -> str:
    return canonical_path.replace(SEP, path.sep)


def canon_path(native_path: str | os.PathLike[str], /) -> str:
    """Return path in OS-independent form"""
    return os.fspath(native_path).replace(path.sep, SEP)


def path_stabilize(filepath: str | os.PathLike[str], /) -> str:
    "Normalize path separator and unicode string"
    new_path = canon_path(filepath)
    return unicodedata.normalize('NFC', new_path)


def relative_uri(base: str, to: str) -> str:
    """Return a relative URL from ``base`` to ``to``."""
    if to.startswith(SEP):
        return to
    b2 = base.split('#')[0].split(SEP)
    t2 = to.split('#')[0].split(SEP)
    # remove common segments (except the last segment)
    for x, y in zip(b2[:-1], t2[:-1]):
        if x != y:
            break
        b2.pop(0)
        t2.pop(0)
    if b2 == t2:
        # Special case: relative_uri('f/index.html','f/index.html')
        # returns '', not 'index.html'
        return ''
    if len(b2) == 1 and t2 == ['']:
        # Special case: relative_uri('f/index.html','f/') should
        # return './', not ''
        return '.' + SEP
    return ('..' + SEP) * (len(b2) - 1) + SEP.join(t2)


def ensuredir(file: str | os.PathLike[str]) -> None:
    """Ensure that a path exists."""
    os.makedirs(file, exist_ok=True)


def mtimes_of_files(dirnames: list[str], suffix: str) -> Iterator[float]:
    for dirname in dirnames:
        for root, _dirs, files in os.walk(dirname):
            for sfile in files:
                if sfile.endswith(suffix):
                    with contextlib.suppress(OSError):
                        yield path.getmtime(path.join(root, sfile))

def run(self) -> list:
    """Include a file as part of the content of this reST file.

    Depending on the options, the file content (or a clipping) is
    converted to nodes and returned or inserted into the input stream.
    """
    self.settings = settings = self.state.document.settings
    if not settings.file_insertion_enabled:
        raise self.warning('"%s" directive disabled.' % self.name)
    self.tab_width = self.options.get('tab-width', settings.tab_width)
    self.clip_options = (self.options.get('start-line', None),
                         self.options.get('end-line', None),
                         self.options.get('start-after', ''),
                         self.options.get('end-before', ''))
    path = directives.path(self.arguments[0])
    if path.startswith('<') and path.endswith('>'):
        path = '/' + path[1:-1]
        root_prefix = self.standard_include_path
    else:
        root_prefix = settings.root_prefix
    path = adapt_path(path,
                      self.state.document.current_source,
                      root_prefix)
    self.options['source'] = path

    inputstring = self.read_file(path)

    if 'literal' in self.options:
        return self.as_literal_block(inputstring)
    if 'code' in self.options:
        return self.as_code_block(inputstring)
    if 'parser' in self.options:
        return self.custom_parse(inputstring)
    self.insert_into_input_lines(inputstring)
    return []

